-- Populate attribute_schema for all marketplace leaf subcategories per the
-- Marketplace Category & Listing System PRD (2026-08-31). Additive-only: only
-- UPDATEs the JSONB attribute_schema column on existing mkt_categories rows,
-- no DDL, no new tables, no rows inserted/removed. Top-level category rows
-- (Vehicles, Property, ...) are left as '{}' since listings are always created
-- against a leaf subcategory, never a top-level category.
--
-- Each JSONB value carries two independent, coexisting shapes read by two
-- different consumers:
--   "fields"  -> consumed only by the mobile client (form rendering: widget
--                type, label, group, options, unit, placeholder). See
--                mobile-app/reactnative/.../api/sell.mock.ts AttributeField.
--   "required"/"properties"/"additionalProperties" -> consumed only by
--                backend/internal/marketplace/attrs_validation.go (server-side
--                write-time validation). Each ignores the other's keys.
--
-- Idempotent: every statement is an unconditional UPDATE keyed by
-- (market_id, slug), safe to re-run.

UPDATE mkt_categories SET attribute_schema = $jsonb${"fields":[{"key":"listing_type","label":"Listing Type","type":"segmented","required":true,"filterable":true,"group":"Service Details","options":[{"value":"prepared_meal","label":"Prepared Meal"},{"value":"catering_service","label":"Catering Service"}]},{"key":"cuisine_type","label":"Cuisine Type","type":"multiselect","filterable":true,"group":"Service Details","options":[{"value":"nigerian","label":"Nigerian"},{"value":"continental","label":"Continental"},{"value":"chinese","label":"Chinese"},{"value":"pastries","label":"Pastries"}]},{"key":"minimum_order","label":"Minimum Order","type":"number","group":"Service Details"},{"key":"serves","label":"Serves (persons)","type":"number","unit":"persons","group":"Service Details"},{"key":"unit_of_sale","label":"Unit of Sale","type":"select","required":true,"filterable":true,"group":"Sale Details","options":[{"value":"per_item","label":"Per Item"},{"value":"per_kg","label":"Per Kg"},{"value":"per_bag_sack","label":"Per Bag/Sack"},{"value":"per_basket","label":"Per Basket"},{"value":"per_crate","label":"Per Crate"},{"value":"per_litre","label":"Per Litre"},{"value":"lump_sum","label":"Lump Sum"}]},{"key":"quantity_available","label":"Quantity Available","type":"number","group":"Sale Details"},{"key":"delivery_available","label":"Delivery Available","type":"toggle","filterable":true,"group":"Sale Details"}],"required":["listing_type","unit_of_sale"],"properties":{"listing_type":{"type":"string","enum":["prepared_meal","catering_service"]},"cuisine_type":{"type":"array","items":{"type":"string","enum":["nigerian","continental","chinese","pastries"]}},"minimum_order":{"type":"number"},"serves":{"type":"number"},"unit_of_sale":{"type":"string","enum":["per_item","per_kg","per_bag_sack","per_basket","per_crate","per_litre","lump_sum"]},"quantity_available":{"type":"number"},"delivery_available":{"type":"boolean"}},"additionalProperties":false}$jsonb$::jsonb, updated_at = now()
  WHERE market_id = 'NG' AND slug = 'agric-catering';

